package com.example.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.staticCompositionLocalOf

val LocalThemeColors = staticCompositionLocalOf<ThemeColors> { error("ThemeColors are only provided inside AppTheme") }

@Composable
fun AppTheme(
    isDark: Boolean = isSystemInDarkTheme(),
    content: @Composable () -> Unit,
) {
    val colors = rememberThemeColors(
        seedColor = SeedColor,
        isDark = isDark,
    )

    CompositionLocalProvider(LocalThemeColors provides colors, content = content)
}
